// The calendar's data model: what an event is, how a repeat becomes a list of
// occurrences, and what "edit" means when the thing you clicked is one of
// hundreds generated by a rule.
//
// Pure functions only — no localStorage, no React. plannerStore.js owns the
// storage and the change events; this file owns the meaning. That split is why
// the whole model can be tested in node against real dates.
//
// ── The shape ────────────────────────────────────────────────────────────────
//
//   {
//     id, calendarId, title, notes, location, color,
//     allDay:    false,
//     date:      '2026-10-08',   // the first (or only) day
//     startTime: '09:00',        // ignored when allDay
//     endDate:   '2026-10-08',   // later than date for a multi-day event
//     endTime:   '10:00',
//     rrule:     null | { freq, interval, byDay, … },   // see recurrence.js
//     exdates:   ['2026-10-15'], // occurrences deleted one at a time
//     overrides: { '2026-10-22': { startTime:'11:00' } },  // edited one at a time
//     alerts:    [{ minutesBefore: 10 }],
//     v: 2
//   }
//
// `date`, `startTime` and `endTime` keep the names and meanings they had in v1
// on purpose: the dashboard, the habit bridge and the undo timeline all read
// them, and a rename would have been a migration for no gain. What v2 actually
// changes is that the five-value `recur` string becomes an rrule object, and
// that an occurrence can now be deleted or edited on its own.
//
// ── Occurrences ──────────────────────────────────────────────────────────────
//
// An event in storage is a template. What a view draws is an *occurrence*: the
// template resolved for one particular date, carrying `occDate` (which date of
// the series it is) and `instanceId` (unique per occurrence, so selection and
// drag state can address a single one). Nothing writes an occurrence back —
// edits go through editEvent/deleteEvent with a scope, which is the only place
// that decides whether the master, an override, or a split is the right answer.

import { occurrenceDates, parseDate, dateKey, ruleFromLegacyRecur } from './recurrence';

export const MODEL_VERSION = 2;

// Everyone starts with these two, so the sidebar is never an empty list and an
// event always has somewhere to belong.
export const DEFAULT_CALENDARS = [
  { id: 'personal', name: 'Personal', color: 'blue',  visible: true },
  { id: 'work',     name: 'Work',     color: 'amber', visible: true },
];

const pad = (n) => String(n).padStart(2, '0');
export const timeToMinutes = (t) => { const [h, m] = String(t || '0:0').split(':').map(Number); return (h || 0) * 60 + (m || 0); };
export const minutesToTime = (m) => `${pad(Math.floor(m / 60))}:${pad(m % 60)}`;
export const addDaysStr = (dateStr, n) => { const d = parseDate(dateStr); d.setDate(d.getDate() + n); return dateKey(d); };
export const daysBetween = (aStr, bStr) => Math.round((parseDate(bStr) - parseDate(aStr)) / 86400000);

// ── Migration ────────────────────────────────────────────────────────────────

// v1 blocks carried a `recur` string and nothing else. Turning that into a rule
// is lossless (proved against the old predicate over 400 days), and every new
// field gets the value that keeps the event looking exactly as it did.
export function migrateEvent(block) {
  if (!block || typeof block !== 'object') return null;
  if (block.v === MODEL_VERSION) return block;
  const date = String(block.date || '').slice(0, 10);
  if (!date) return null;
  const out = {
    id: block.id ?? Date.now() + Math.random(),
    calendarId: block.calendarId || 'personal',
    title: block.title || '',
    notes: block.note || block.notes || '',
    location: block.location || '',
    color: block.color || 'blue',
    allDay: !!block.allDay,
    date,
    startTime: block.startTime || '09:00',
    endDate: String(block.endDate || date).slice(0, 10),
    endTime: block.endTime || '10:00',
    rrule: block.rrule || ruleFromLegacyRecur(block.recur, date),
    exdates: Array.isArray(block.exdates) ? block.exdates : [],
    overrides: (block.overrides && typeof block.overrides === 'object') ? block.overrides : {},
    // v1 notified at the start and at the end; "at the start" is the alert a
    // calendar has, so that is what carries over.
    alerts: Array.isArray(block.alerts) ? block.alerts : [{ minutesBefore: 0 }],
    v: MODEL_VERSION,
  };
  // An end before the start used to be impossible to represent; clamp rather
  // than drop, so a corrupt row still shows up where the user can fix it.
  if (!out.allDay && out.endDate === out.date && timeToMinutes(out.endTime) <= timeToMinutes(out.startTime)) {
    out.endTime = minutesToTime(Math.min(24 * 60 - 1, timeToMinutes(out.startTime) + 60));
  }
  return out;
}

export function migrateEvents(blocks) {
  if (!Array.isArray(blocks)) return [];
  return blocks.map(migrateEvent).filter(Boolean);
}

export function needsMigration(blocks) {
  return Array.isArray(blocks) && blocks.some(b => b && b.v !== MODEL_VERSION);
}

// ── Expansion ────────────────────────────────────────────────────────────────

// How many days an event covers, so a multi-day occurrence can be drawn on
// every day it touches. Span is a property of the template, not of the
// occurrence, which is what lets a repeating 3-day event work.
function spanDays(event) {
  const d = daysBetween(event.date, event.endDate || event.date);
  return d > 0 ? d : 0;
}

// One occurrence, with the override for that date already folded in.
function materialize(event, occDate) {
  const override = event.overrides?.[occDate];
  const base = override ? { ...event, ...override } : event;
  // An override may move the event to another day; its own date wins.
  const startDate = override?.date || occDate;
  const span = override?.endDate && override?.date
    ? Math.max(0, daysBetween(override.date, override.endDate))
    : spanDays(event);
  return {
    ...base,
    date: startDate,
    endDate: addDaysStr(startDate, span),
    eventId: event.id,
    occDate,
    instanceId: `${event.id}:${occDate}`,
    isRecurring: !!event.rrule,
    isDetached: !!override,
    span,
  };
}

// Every occurrence that touches any day in [fromStr, toStr].
//
// The window is widened backwards by the event's span before asking the rule,
// because a 3-day event starting the day before the window still shows inside
// it — the classic off-by-one that makes multi-day events vanish at week
// boundaries.
export function expandRange(events, fromStr, toStr) {
  const out = [];
  for (const event of events || []) {
    if (!event || !event.date) continue;
    const span = spanDays(event);
    const searchFrom = span > 0 ? addDaysStr(fromStr, -span) : fromStr;
    const dates = occurrenceDates(event.date, event.rrule, searchFrom, toStr);
    for (const occDate of dates) {
      if (event.exdates?.includes(occDate)) continue;
      const occ = materialize(event, occDate);
      // A moved occurrence can land outside the window it was found in.
      if (occ.endDate < fromStr || occ.date > toStr) continue;
      out.push(occ);
    }
    // An occurrence moved INTO this window from outside it would otherwise be
    // missed, because the rule never produces a date inside the window for it.
    for (const [occDate, override] of Object.entries(event.overrides || {})) {
      if (occDate >= searchFrom && occDate <= toStr) continue;   // already handled
      if (event.exdates?.includes(occDate)) continue;
      const movedTo = override?.date;
      if (!movedTo) continue;
      const occ = materialize(event, occDate);
      if (occ.endDate < fromStr || occ.date > toStr) continue;
      out.push(occ);
    }
  }
  return out.sort(compareOccurrences);
}

export function expandDay(events, dateStr) {
  return expandRange(events, dateStr, dateStr);
}

// All-day and multi-day events sort above timed ones — that is the order the
// all-day strip reads in, and within a day timed events go by start time.
export function compareOccurrences(a, b) {
  const aAll = a.allDay || a.span > 0;
  const bAll = b.allDay || b.span > 0;
  if (aAll !== bAll) return aAll ? -1 : 1;
  if (aAll && bAll) {
    if (a.date !== b.date) return a.date < b.date ? -1 : 1;
    return b.span - a.span;    // longer bars first, so shorter ones nest under
  }
  if (a.date !== b.date) return a.date < b.date ? -1 : 1;
  const d = timeToMinutes(a.startTime) - timeToMinutes(b.startTime);
  if (d) return d;
  return timeToMinutes(a.endTime) - timeToMinutes(b.endTime);
}

// Where an occurrence sits on one particular day's time grid, in minutes from
// midnight — clipped to that day, with flags for the arrows that say "this
// continues". A timed event crossing midnight is clipped the same way a
// multi-day one is, which is why the grid never has to know about spans.
export function daySlice(occ, dateStr) {
  const startsHere = occ.date === dateStr;
  const endsHere = occ.endDate === dateStr;
  return {
    startM: startsHere ? timeToMinutes(occ.startTime) : 0,
    endM: endsHere ? timeToMinutes(occ.endTime) : 24 * 60,
    continuesBefore: !startsHere,
    continuesAfter: !endsHere,
  };
}

// Timed occurrences for a day, with all-day and multi-day bars taken out: the
// grid draws these, the strip above it draws the rest.
export function timedForDay(occurrences, dateStr) {
  return occurrences
    .filter(o => !o.allDay && o.span === 0 && o.date === dateStr)
    .sort(compareOccurrences);
}

export function allDayForDay(occurrences, dateStr) {
  return occurrences
    .filter(o => (o.allDay || o.span > 0) && o.date <= dateStr && o.endDate >= dateStr)
    .sort(compareOccurrences);
}

// ── Editing ──────────────────────────────────────────────────────────────────
//
// Three scopes, the same three Apple offers when you change something that
// repeats. 'this' and 'future' only mean anything for a repeating event; for a
// one-off every scope is the same edit.

export const SCOPES = ['this', 'future', 'all'];

// Fields that describe the series rather than one occurrence. Changing one of
// these for a single occurrence makes no sense, so they are dropped from a
// 'this' patch instead of silently corrupting the rule.
const SERIES_FIELDS = new Set(['rrule', 'exdates', 'overrides', 'id', 'v']);

function stripSeriesFields(patch) {
  const out = {};
  for (const [k, v] of Object.entries(patch || {})) if (!SERIES_FIELDS.has(k)) out[k] = v;
  return out;
}

function newId() { return Date.now() + Math.floor(Math.random() * 1000); }

// Returns a NEW events array. `occDate` says which occurrence was clicked; it
// is required for 'this' and 'future' and ignored for 'all'.
export function editEvent(events, eventId, occDate, scope, patch) {
  const list = events || [];
  const event = list.find(e => e.id === eventId);
  if (!event) return list;

  // Without a rule there is one occurrence, so every scope edits the master.
  if (!event.rrule || scope === 'all') {
    return list.map(e => (e.id === eventId ? { ...e, ...patch } : e));
  }

  if (scope === 'this') {
    const clean = stripSeriesFields(patch);
    // An override holds only what differs, so later edits to the series still
    // reach this occurrence for everything the user didn't touch here.
    const merged = { ...(event.overrides?.[occDate] || {}), ...clean };
    return list.map(e => (e.id === eventId
      ? { ...e, overrides: { ...(e.overrides || {}), [occDate]: merged } }
      : e));
  }

  // 'future': the series is cut the day before this occurrence and a second
  // event carries the change forward. That is how iCalendar does it too, and it
  // keeps past occurrences exactly as they were recorded.
  const cutoff = addDaysStr(occDate, -1);
  const keptOverrides = {};
  for (const [k, v] of Object.entries(event.overrides || {})) if (k <= cutoff) keptOverrides[k] = v;
  const movedOverrides = {};
  for (const [k, v] of Object.entries(event.overrides || {})) if (k > cutoff) movedOverrides[k] = v;

  const head = {
    ...event,
    rrule: { ...event.rrule, until: cutoff, count: null },
    exdates: (event.exdates || []).filter(d => d <= cutoff),
    overrides: keptOverrides,
  };
  const tail = {
    ...event,
    ...stripSeriesFields(patch),
    id: newId(),
    date: patch?.date || occDate,
    endDate: patch?.endDate || addDaysStr(patch?.date || occDate, spanDays(event)),
    // A count'ed series that is split loses its count on the head, so the tail
    // keeps the remainder open-ended rather than guessing a number.
    rrule: { ...event.rrule, until: event.rrule.until || null },
    exdates: (event.exdates || []).filter(d => d > cutoff),
    overrides: movedOverrides,
  };
  // Cutting before the first occurrence leaves nothing behind.
  const out = head.rrule.until >= event.date ? [head, tail] : [tail];
  return list.flatMap(e => (e.id === eventId ? out : [e]));
}

export function deleteEvent(events, eventId, occDate, scope) {
  const list = events || [];
  const event = list.find(e => e.id === eventId);
  if (!event) return list;

  if (!event.rrule || scope === 'all') return list.filter(e => e.id !== eventId);

  if (scope === 'this') {
    const exdates = [...new Set([...(event.exdates || []), occDate])];
    const overrides = { ...(event.overrides || {}) };
    delete overrides[occDate];
    return list.map(e => (e.id === eventId ? { ...e, exdates, overrides } : e));
  }

  // 'future' — stop the series the day before.
  const cutoff = addDaysStr(occDate, -1);
  if (cutoff < event.date) return list.filter(e => e.id !== eventId);
  const overrides = {};
  for (const [k, v] of Object.entries(event.overrides || {})) if (k <= cutoff) overrides[k] = v;
  return list.map(e => (e.id === eventId
    ? { ...e, rrule: { ...e.rrule, until: cutoff, count: null }, exdates: (e.exdates || []).filter(d => d <= cutoff), overrides }
    : e));
}

// Dragging an occurrence is a move by whole days plus a time change, which has
// to become the right scoped edit — the one place a view is allowed to express
// "the user dropped this here" without knowing about overrides.
export function moveOccurrence(events, occ, newDateStr, newStartM, scope = 'this') {
  const event = (events || []).find(e => e.id === occ.eventId);
  if (!event) return events || [];
  const duration = occ.allDay ? 0 : timeToMinutes(occ.endTime) - timeToMinutes(occ.startTime);
  const patch = { date: newDateStr, endDate: addDaysStr(newDateStr, occ.span || 0) };
  if (!occ.allDay) {
    const start = Math.max(0, Math.min(24 * 60 - 15, newStartM));
    patch.startTime = minutesToTime(start);
    patch.endTime = minutesToTime(Math.min(24 * 60 - 1, start + Math.max(15, duration)));
  }
  return editEvent(events, occ.eventId, occ.occDate, scope, patch);
}

// ── Search ───────────────────────────────────────────────────────────────────

// Searching has to look at the templates, not a window of occurrences, or the
// result depends on which month you happened to be looking at. Matches are then
// expanded to their next occurrences so the results list can show real dates.
export function searchEvents(events, query, fromStr, toStr) {
  const q = String(query || '').trim().toLowerCase();
  if (!q) return [];
  const hits = (events || []).filter(e =>
    [e.title, e.notes, e.location].some(f => String(f || '').toLowerCase().includes(q)));
  return expandRange(hits, fromStr, toStr);
}
